# SNAPGATE module - do not edit. Configure via environment variables, not by editing this file.
import logging
from typing import Literal
from urllib.parse import urlsplit

from pydantic_settings import BaseSettings, SettingsConfigDict

logger = logging.getLogger(__name__)

#: A site role, granted only by the SNAPGATE_*_EMAILS lists.
SiteRole = Literal["superadmin", "admin"]


def _email_set(raw: str) -> set[str]:
    return {e.strip().lower() for e in raw.split(",") if e.strip()}


class AuthSettings(BaseSettings):
    """
    Authentication settings from environment variables.

    DO NOT EDIT THIS FILE. All settings are configured via environment variables.
    Set them in your .env file or shell environment - pydantic-settings reads
    env vars matching these field names automatically.

    Example .env:
        OIDC_ISSUER=https://accounts.example.org
        OIDC_CLIENT_ID=myapp
        ACCESS_TOKEN_EXPIRE_MINUTES=30
        DEMO_LOGIN=true

    Default values are for testing only. Override in production via env vars.
    """

    # Sign-in through exactly ONE OpenID Connect issuer (defaults for testing
    # only). An app that needs a choice of providers points at a broker that
    # offers them, never at several issuers.
    OIDC_ISSUER: str = "http://localhost:8200"
    OIDC_CLIENT_ID: str = "test-client-id"
    OIDC_CLIENT_SECRET: str = "test-client-secret"
    OIDC_REDIRECT_URI: str = "http://localhost:8000/auth/login/callback"
    OIDC_LABEL: str = "your account"  # Sign-in button text: "Sign in with <label>"
    OIDC_SCOPES: str = "openid email profile"
    # An id_token claim naming a user's OLD key (a bare User.google_id). On a
    # first sign-in with no row under issuer#sub, the row whose google_id equals
    # this claim is re-keyed instead of a new user being made. Read only on that
    # miss, so leave it set. E.g. google_sub (moving from Google to a broker
    # that sends it), or sub (staying on Google itself).
    OIDC_ADOPT_CLAIM: str | None = None
    # The origin that serves snapgate's /auth/* routes (the API host). When
    # set, OIDC_REDIRECT_URI must be on it. Not FRONTEND_URL: a split-host app
    # (api.example.com vs example.com) puts the callback on the API host.
    PUBLIC_URL: str | None = None

    # Security Keys (defaults for testing only - override in production!)
    JWT_SECRET_KEY: str = "test-jwt-secret-key-must-be-32-chars-long"
    JWT_PRIVATE_KEY: str | None = None  # For RS256 (optional)
    JWT_PUBLIC_KEY: str | None = None  # For RS256 (optional)
    SESSION_SECRET_KEY: str = "test-session-secret-key-32-chars!"

    # Token Configuration
    ACCESS_TOKEN_EXPIRE_MINUTES: int = 15
    REFRESH_TOKEN_EXPIRE_DAYS: int = 30
    ACCESS_TOKEN_ALGORITHM: Literal["HS256", "RS256"] = "HS256"

    # Frontend URLs (can be multiple for staging/prod)
    FRONTEND_URL: str = "http://localhost:3000"
    ALLOWED_ORIGINS: str | None = None  # Comma-separated list of allowed origins

    # API Keys
    API_KEY_PREFIX: str = "snapgate_"  # Prefix on generated API keys, e.g. "authormark_"
    # Verified-token cache (api_keys.authenticate_api_key): repeat requests with
    # the same key skip bcrypt. Bounded LRU of sha256(token) -> key id; the key
    # and its user are still re-read and checked on every request.
    API_KEY_VERIFY_CACHE_SIZE: int = 256
    API_KEY_VERIFY_CACHE_S: float = 300.0
    # last_used_at is written at most once per this many seconds per key.
    API_KEY_LAST_USED_RESOLUTION_S: int = 60

    # Rate Limiting
    RATE_LIMIT_ENABLED: bool = True
    RATE_LIMIT_PER_MINUTE: int = 10  # Max requests per minute per IP

    # Counters live in this process. snapgate assumes a single-process
    # deployment; running several workers would give each its own counters and
    # multiply the effective limit by the worker count.
    #
    # Request header carrying the true client IP, e.g. "CF-Connecting-IP" or
    # "X-Real-IP". Only set this when a trusted proxy OVERWRITES the header on
    # every request — an unset/untrusted header is client-spoofable. None
    # (default) keeps the socket peer address (``request.client.host``).
    RATE_LIMIT_CLIENT_IP_HEADER: str | None = None

    # Development/Testing
    DEBUG: bool = False  # General dev flag for the host app; no effect on auth
    # Mounts POST /auth/demo-login/{role}, which creates APPROVED users.
    # Local development only; never set against a database with real users.
    DEMO_LOGIN: bool = False

    # Site admins (snapgate.useradmin). Comma-separated, case-insensitive.
    # Listed people are approved at every sign-in and cannot be suspended or
    # demoted through the API. Only these lists grant site roles.
    SNAPGATE_SUPERADMIN_EMAILS: str = ""
    SNAPGATE_ADMIN_EMAILS: str = ""

    # Database
    DATABASE_URL: str = "postgresql://user:pass@localhost/myapp"

    model_config = SettingsConfigDict(env_file=".env", case_sensitive=True, extra="ignore")

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        # Validate critical settings on initialization
        if len(self.JWT_SECRET_KEY) < 32:
            raise ValueError("JWT_SECRET_KEY must be at least 32 characters")
        if len(self.SESSION_SECRET_KEY) < 32:
            raise ValueError("SESSION_SECRET_KEY must be at least 32 characters")

        # Validate RS256 requirements
        if self.ACCESS_TOKEN_ALGORITHM == "RS256" and (
            not self.JWT_PRIVATE_KEY or not self.JWT_PUBLIC_KEY
        ):
            raise ValueError("RS256 requires JWT_PRIVATE_KEY and JWT_PUBLIC_KEY")

        self._check_oidc()

        # Parse allowed origins from comma-separated string to list
        if self.ALLOWED_ORIGINS:
            self._allowed_origins_list = [o.strip() for o in self.ALLOWED_ORIGINS.split(",")]
        else:
            self._allowed_origins_list = [self.FRONTEND_URL]

        logger.info("Auth settings loaded successfully")

    def _check_oidc(self) -> None:
        """Normalize OIDC_ISSUER and refuse settings that cannot work safely."""
        self.OIDC_ISSUER = self.OIDC_ISSUER.strip().rstrip("/")
        for name in ("OIDC_ISSUER", "OIDC_CLIENT_ID", "OIDC_CLIENT_SECRET", "OIDC_REDIRECT_URI"):
            if not getattr(self, name).strip():
                raise ValueError(f"{name} is required")
        issuer = urlsplit(self.OIDC_ISSUER)
        loopback = issuer.hostname in ("localhost", "127.0.0.1")
        if issuer.scheme != "https" and not (issuer.scheme == "http" and loopback):
            raise ValueError("OIDC_ISSUER must be https (http only for localhost)")
        if "openid" not in self.OIDC_SCOPES.split():
            raise ValueError("OIDC_SCOPES must include openid")
        redirect = urlsplit(self.OIDC_REDIRECT_URI)
        local = redirect.hostname in ("localhost", "127.0.0.1")
        if redirect.scheme != "https" and not (redirect.scheme == "http" and local):
            raise ValueError("OIDC_REDIRECT_URI must be https (http only for localhost)")
        if self.PUBLIC_URL:
            public = urlsplit(self.PUBLIC_URL.strip())
            origin = f"{public.scheme}://{public.netloc}"
            if f"{redirect.scheme}://{redirect.netloc}" != origin:
                raise ValueError(f"OIDC_REDIRECT_URI must be on PUBLIC_URL's origin ({origin})")

    def site_role_for(self, email: str | None) -> SiteRole | None:
        """``superadmin`` > ``admin`` > None, from the env lists (parsed on each call)."""
        if not email:
            return None
        email = email.strip().lower()
        if email in _email_set(self.SNAPGATE_SUPERADMIN_EMAILS):
            return "superadmin"
        if email in _email_set(self.SNAPGATE_ADMIN_EMAILS):
            return "admin"
        return None

    @property
    def allowed_origins(self) -> list[str]:
        """List of allowed CORS origins."""
        return self._allowed_origins_list


# Global instance
settings = AuthSettings()
